<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; class Puja extends Model { use SoftDeletes; protected $fillable=['puja_category_id','name','slug','image','excerpt','description','benefits','samagri','duration','price','location','is_featured']; protected function casts(): array{return ['benefits'=>'array','samagri'=>'array','is_featured'=>'boolean'];} public function category(){return $this->belongsTo(PujaCategory::class,'puja_category_id');} public function slots(){return $this->hasMany(BookingSlot::class);} public function bookings(){return $this->hasMany(PujaBooking::class);} }
